(()=>{'use strict';
const C=window.MCL_SUPABASE||{},sb=window.supabase.createClient(C.url,C.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}),$=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)],esc=(s='')=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m])),money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),fmt=d=>d?new Date(`${d}T12:00:00`).toLocaleDateString('pt-BR'):'—',today=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10),monthKey=d=>(d||today()).slice(0,7),uid=()=>crypto.randomUUID();
let user=null,profile=null,view='dashboard',selectedMonth=monthKey(),db={accounts:[],payments:[],documents:[],cashflow:[],budgets:[],trips:[],planning:[],revenues:[],natures:[],sectors:[],profiles:[]};
const admin=()=>profile?.tipo==='Administrador';
function matrix(on){document.body.classList.toggle('login-mode',!!on);const c=$('#matrix');if(!on||!c)return;const x=c.getContext('2d');let drops=[];const resize=()=>{c.width=innerWidth;c.height=innerHeight;drops=Array(Math.ceil(innerWidth/18)).fill(0).map(()=>Math.random()*50)};resize();const chars='01MCLFINANCEIRO<>[]{}R$'.split('');(function draw(){if(!document.body.classList.contains('login-mode'))return;x.fillStyle='rgba(29,33,57,.15)';x.fillRect(0,0,c.width,c.height);x.fillStyle='rgba(239,88,65,.45)';x.font='14px monospace';drops.forEach((y,i)=>{x.fillText(chars[Math.floor(Math.random()*chars.length)],i*18,y*18);if(y*18>c.height&&Math.random()>.975)drops[i]=0;drops[i]+=.45});requestAnimationFrame(draw)})()}
function toast(msg,type='ok'){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';Object.assign(t.style,{position:'fixed',right:'18px',bottom:'18px',zIndex:100,padding:'12px 16px',borderRadius:'12px',color:'#fff',fontWeight:'800',boxShadow:'0 12px 35px rgba(0,0,0,.22)'});document.body.append(t)}t.style.background=type==='error'?'#C62828':'#1D2139';t.textContent=msg;t.style.display='block';clearTimeout(t._tm);t._tm=setTimeout(()=>t.style.display='none',3200)}
function modal(title,body,wide=false){const b=document.createElement('div');b.className='modal-backdrop';b.innerHTML=`<section class="modal"${wide?' style="width:min(1000px,96vw)"':''}><div class="modal-head"><h3>${esc(title)}</h3><button class="btn ghost small" data-close>Fechar</button></div>${body}</section>`;document.body.append(b);b.querySelectorAll('.field').forEach((field,n)=>{const label=field.querySelector('label'),input=field.querySelector('input,select,textarea');if(label&&input){if(!input.id)input.id='field-'+uid();label.htmlFor=input.id}});b.querySelector('[data-close]').onclick=()=>b.remove();return b}
async function invoke(fn,body){const {data:{session}}=await sb.auth.getSession();const r=await fetch(`${C.url}/functions/v1/${fn}`,{method:'POST',headers:{'Content-Type':'application/json',apikey:C.publishableKey,...(session?.access_token?{Authorization:`Bearer ${session.access_token}`}:{})},body:JSON.stringify(body)});const j=await r.json().catch(()=>({}));if(!r.ok||j.ok===false)throw new Error(j.error||'Falha na operação');return j}
async function profileFor(u){const {data,error}=await sb.from('profiles').select('*').eq('id',u.id).maybeSingle();if(error)throw error;if(!data)throw new Error('Perfil não encontrado.');if(data.ativo===false)throw new Error('Usuário inativo.');return data}
async function bootstrap(){const {data:{session}}=await sb.auth.getSession();if(!session){login();return}try{user=session.user;profile=await profileFor(user);await load();app()}catch(e){await sb.auth.signOut();login(e.message)}}
function login(message=''){matrix(true);$('#app').innerHTML=`<main class="login-wrap"><section class="login-card"><img class="login-logo" src="logo-mcl-positiva.svg?v=20260927-2" alt="Minha Casa Legal"><h1>Minha Casa Legal Financeiro</h1><div class="sub">Gestão financeira, orçamentária e documental</div><form id="loginForm"><div class="field"><label>E-mail</label><input name="email" type="email" required></div><div class="field"><label>Senha</label><input name="password" type="password" required></div><button class="btn wide">Entrar</button><div class="login-error">${esc(message)}</div></form><button class="btn ghost wide" id="firstAdmin" style="margin-top:8px">Criar primeiro administrador</button></section></main>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),{error}=await sb.auth.signInWithPassword({email:String(f.get('email')).trim(),password:String(f.get('password'))});if(error)return $('.login-error').textContent=error.message;location.reload()};$('#firstAdmin').onclick=firstAdmin}
function firstAdmin(){const x=modal('Primeiro administrador',`<form id="boot"><div class="modal-body"><div class="notice orange">Disponível somente enquanto o Financeiro MCL não possui nenhum usuário.</div><div class="field"><label>Nome</label><input name="nome" required></div><div class="field"><label>E-mail</label><input name="email" type="email" required></div><div class="field"><label>Senha</label><input name="password" type="password" minlength="8" required></div></div><div class="modal-foot"><button class="btn">Criar administrador</button></div></form>`);x.querySelector('#boot').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));try{await invoke('bootstrap-admin',o);x.remove();toast('Administrador criado. Faça login.')}catch(err){toast(err.message,'error')}}}
async function load(){const queries=[['financeiro_contas','accounts'],['financeiro_pagamentos','payments'],['financeiro_documentos','documents'],['financeiro_fluxo','cashflow'],['financeiro_orcamentos','budgets'],['financeiro_viagens','trips'],['financeiro_planejamento','planning'],['financeiro_receitas','revenues'],['financeiro_naturezas','natures'],['financeiro_setores','sectors'],['profiles','profiles']];for(const [table,key] of queries){const {data,error}=await sb.from(table).select('*');if(error&&!(error.code==='42501'&&!admin())){console.warn(table,error)}db[key]=data||[]}}
const navAdmin=[['dashboard','Visão Geral'],['accounts','Contas'],['receivables','Recebimentos'],['documents','Documentos Fiscais'],['cashflow','Fluxo de Caixa'],['budgets','Orçamentos'],['trips','Viagens'],['planning','Planejamento'],['reports','Relatórios'],['sep',''],['registers','Cadastros'],['users','Usuários']],navStaff=[['documents','Documentos Fiscais'],['budgets','Meu Orçamento'],['trips','Viagens']];
function app(){matrix(false);const nav=admin()?navAdmin:navStaff;if(!nav.some(([id])=>id===view))view=admin()?'dashboard':'documents';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="logo-mcl.svg?v=20260927-2" alt="Minha Casa Legal"></div><nav class="nav">${nav.map(([id,l])=>id==='sep'?'<div class="sep"></div>':`<button class="${view===id?'active':''}" data-view="${id}">${l}</button>`).join('')}</nav><div class="sidebar-foot"><div class="user-mini"><strong>${esc(profile.nome)}</strong>${esc(profile.tipo||'Usuário')}</div><button class="btn secondary wide" id="logout">Sair</button></div></aside><section class="main"><header class="topbar"><h2 id="title"></h2><span class="badge orange">Minha Casa Legal</span></header><main class="content" id="content"></main></section></div>`;$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;app()});$('#logout').onclick=async()=>{await sb.auth.signOut();location.reload()};render()}
function title(t){$('#title').textContent=t}function empty(t='Nenhum registro encontrado.'){return `<div class="empty">${esc(t)}</div>`}function statusBadge(s=''){const c=/Pago|Paga|Aprovada|Confirmado|Ativa/i.test(s)?'ok':/Vencid|Diverg|Cancel/i.test(s)?'danger':/hoje|Revisar|Pendente/i.test(s)?'warn':'';return `<span class="badge ${c}">${esc(s||'—')}</span>`}
function render(){({dashboard,accounts,receivables:()=>window.MCLRecebimentos?.open(),documents,cashflow,budgets,trips,planning,reports,registers,users}[view]||documents)()}
function paidValue(){return db.payments.filter(p=>/Pago|Paga/i.test(p.status)).reduce((s,p)=>s+Number(p.valor||0),0)+db.cashflow.filter(x=>x.direcao==='Saída').reduce((s,x)=>s+Number(x.valor||0),0)}
function incomeValue(){return db.cashflow.filter(x=>x.direcao==='Entrada').reduce((s,x)=>s+Number(x.valor||0),0)}
function dashboard(){title('Visão Geral');const inc=incomeValue(),out=paidValue(),open=db.payments.filter(p=>!/Pago|Paga/i.test(p.status)).reduce((s,p)=>s+Number(p.valor||0),0),res=inc-out,max=Math.max(1,...db.planning.flatMap(x=>[Number(x.entradas_previstas||0),Number(x.saidas_previstas||0)]));$('#content').innerHTML=`<div class="grid cols-4"><div class="card metric"><h3>Entradas no mês</h3><b>${money(inc)}</b><small>realizadas</small></div><div class="card metric"><h3>Saídas no mês</h3><b>${money(out)}</b><small>pagas/documentadas</small></div><div class="card metric"><h3>Resultado mensal</h3><b class="${res>=0?'kpi-positive':'kpi-negative'}">${money(res)}</b><small>até agora</small></div><div class="card metric"><h3>Contas em aberto</h3><b>${money(open)}</b><small>${db.payments.filter(p=>!/Pago|Paga/i.test(p.status)).length} pagamento(s)</small></div></div><h3 class="section-title">Alertas</h3><div class="grid cols-3"><div class="notice warn">${db.payments.filter(p=>p.vencimento===today()&&!/Pago/i.test(p.status)).length} pagamento(s) vencem hoje.</div><div class="notice danger">${db.payments.filter(p=>p.vencimento<today()&&!/Pago/i.test(p.status)).length} pagamento(s) vencido(s).</div><div class="notice orange">${db.documents.filter(d=>/Revisar/i.test(d.status)).length} documento(s) aguardando revisão.</div></div><h3 class="section-title">Projeção financeira</h3><div class="card">${db.planning.length?`<div class="legend"><span>Entradas</span><span>Saídas</span></div><div class="chart">${db.planning.sort((a,b)=>a.mes.localeCompare(b.mes)).map(p=>`<div class="bar-col"><div class="bar-stack"><i class="bar" style="height:${Number(p.entradas_previstas||0)/max*150}px"></i><i class="bar out" style="height:${Number(p.saidas_previstas||0)/max*150}px"></i></div><b>${money(Number(p.entradas_previstas||0)-Number(p.saidas_previstas||0))}</b><span class="bar-label">${fmt(p.mes)}</span></div>`).join('')}</div>`:empty('Cadastre o planejamento mensal para visualizar a projeção.')}</div>`}
function monthButtons(){const months=[...new Set(db.payments.map(p=>monthKey(p.vencimento)))].sort().reverse();if(!months.includes(selectedMonth))months.unshift(selectedMonth);return `<div class="month-strip">${months.map(m=>`<button class="month-button ${m===selectedMonth?'active':''}" data-month="${m}">${new Date(`${m}-01T12:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</button>`).join('')}</div>`}
function accountName(id){return db.accounts.find(a=>a.id===id)?.nome||'Conta'}
function accounts(){title('Contas');const ps=db.payments.filter(p=>monthKey(p.vencimento)===selectedMonth).sort((a,b)=>a.vencimento.localeCompare(b.vencimento));$('#content').innerHTML=`${monthButtons()}<div class="toolbar"><div class="left"><div class="notice">Contas e boletos ficam separados por mês. Uma conta recorrente pode ter vários pagamentos.</div></div><div class="right"><button class="btn ghost" id="manageNatures">Naturezas</button><button class="btn" id="newAccount">+ Nova conta</button></div></div>${ps.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Conta</th><th>Natureza</th><th>Fornecedor</th><th>Vencimento</th><th>Forma</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody>${ps.map(p=>{const a=db.accounts.find(x=>x.id===p.conta_id)||{};return `<tr><td><b>${esc(a.nome||'Conta')}</b></td><td>${esc(a.categoria||'—')}</td><td>${esc(a.fornecedor||'—')}</td><td>${fmt(p.vencimento)}</td><td>${esc(p.forma_pagamento||'—')}</td><td><b>${money(p.valor)}</b></td><td>${statusBadge(p.status)}</td><td class="actions"><button class="btn small ghost" data-edit-payment="${p.id}">Editar</button><button class="btn small danger" data-del-payment="${p.id}">Excluir</button></td></tr>`}).join('')}</tbody></table></div>`:empty('Nenhuma conta neste mês.')}`;$$('[data-month]').forEach(b=>b.onclick=()=>{selectedMonth=b.dataset.month;accounts()});$('#newAccount').onclick=()=>accountForm();$('#manageNatures').onclick=registers;$$('[data-edit-payment]').forEach(b=>b.onclick=()=>paymentForm(b.dataset.editPayment));$$('[data-del-payment]').forEach(b=>b.onclick=()=>deletePayment(b.dataset.delPayment))}
function accountForm(){const natures=db.natures.filter(n=>n.ativo!==false),sectors=db.sectors.filter(s=>s.ativo!==false);const x=modal('Nova conta',`<form id="accountForm"><div class="modal-body"><div class="form-grid"><div class="field"><label>Conta</label><input name="nome" required></div><div class="field"><label>Fornecedor</label><input name="fornecedor"></div><div class="field"><label>Natureza</label><select name="categoria">${natures.map(n=>`<option>${esc(n.nome)}</option>`).join('')}</select></div><div class="field"><label>Setor</label><select name="setor">${sectors.map(s=>`<option>${esc(s.nome)}</option>`).join('')}</select></div><div class="field"><label>Matrícula / cadastro</label><input name="matricula_cadastro"></div><div class="field"><label>Recorrência</label><select name="recorrencia"><option>Única</option><option>Mensal</option></select></div><div class="field"><label>Quantidade de parcelas</label><input name="parcelas" type="number" min="1" max="60" value="1"></div><div class="field"><label>Primeiro vencimento</label><input name="vencimento" type="date" value="${today()}" required></div><div class="field"><label>Valor por parcela</label><input name="valor" type="number" step="0.01" min="0" required></div><div class="field"><label>Forma de pagamento</label><select name="forma"><option>Boleto</option><option>PIX</option><option>Transferência</option><option>Débito</option><option>Cartão</option><option>Outro</option></select></div><div class="field full"><label>Código / linha digitável / chave</label><input name="codigo"></div></div></div><div class="modal-foot"><button class="btn">Cadastrar conta</button></div></form>`);x.querySelector('#accountForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),id=uid(),count=Math.max(1,Number(f.parcelas||1));try{const {error}=await sb.from('financeiro_contas').insert({id,nome:f.nome,fornecedor:f.fornecedor||null,categoria:f.categoria||null,setor:f.setor||null,matricula_cadastro:f.matricula_cadastro||null,recorrencia:f.recorrencia,ativo:true,criado_por:user.id});if(error)throw error;const base=new Date(`${f.vencimento}T12:00:00`),rows=[];for(let i=0;i<count;i++){const d=new Date(base.getFullYear(),base.getMonth()+i,1,12);d.setDate(Math.min(base.getDate(),new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));rows.push({id:uid(),conta_id:id,vencimento:d.toISOString().slice(0,10),valor:Number(f.valor||0),status:'Pendente',forma_pagamento:f.forma,codigo_pagamento:f.codigo||null,dados:{parcela:i+1,total:count}})}const r=await sb.from('financeiro_pagamentos').insert(rows);if(r.error)throw r.error;x.remove();await load();accounts();toast('Conta cadastrada.')}catch(err){toast(err.message,'error')}}}
function paymentForm(id){const p=db.payments.find(x=>x.id===id);if(!p)return;const x=modal(`Editar • ${accountName(p.conta_id)}`,`<form id="paymentForm"><div class="modal-body"><div class="form-grid"><div class="field"><label>Vencimento</label><input name="vencimento" type="date" value="${p.vencimento}" required></div><div class="field"><label>Valor</label><input name="valor" type="number" step="0.01" value="${Number(p.valor||0)}" required></div><div class="field"><label>Forma</label><select name="forma_pagamento"><option>Boleto</option><option>PIX</option><option>Transferência</option><option>Débito</option><option>Cartão</option><option>Outro</option></select></div><div class="field"><label>Status</label><select name="status"><option>Pendente</option><option>Pago</option><option>Vencido</option><option>Cancelado</option></select></div><div class="field full"><label>Código / pagamento</label><input name="codigo_pagamento" value="${esc(p.codigo_pagamento||'')}"></div></div></div><div class="modal-foot"><button class="btn">Salvar alterações</button></div></form>`);const f=x.querySelector('#paymentForm');f.forma_pagamento.value=p.forma_pagamento||'Boleto';f.status.value=p.status||'Pendente';f.onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.valor=Number(o.valor);o.pago_em=o.status==='Pago'?(p.pago_em||new Date().toISOString()):null;const {error}=await sb.from('financeiro_pagamentos').update(o).eq('id',id);if(error)return toast(error.message,'error');x.remove();await load();accounts();toast('Pagamento atualizado.')}}
async function deletePayment(id){if(!confirm('Excluir este pagamento? A conta principal será preservada.'))return;const {error}=await sb.from('financeiro_pagamentos').delete().eq('id',id);if(error)return toast(error.message,'error');await load();accounts();toast('Pagamento excluído.')}
function documents(){title('Documentos Fiscais');$('#content').innerHTML=`<div class="dropzone"><h3>Enviar documentos</h3><div class="muted">PDF, JPG ou PNG • arquivo armazenado no Supabase Financeiro MCL</div><button class="btn orange" id="uploadDoc" style="margin-top:12px">Enviar documento</button></div><h3 class="section-title">Documentos processados</h3>${db.documents.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Documento</th><th>Fornecedor</th><th>Data</th><th>Natureza</th><th>Setor</th><th>Valor</th><th>Status</th></tr></thead><tbody>${db.documents.sort((a,b)=>(b.data_documento||'').localeCompare(a.data_documento||'')).map(d=>`<tr data-doc-id="${esc(d.id)}"><td><b>${esc(d.nome)}</b></td><td>${esc(d.fornecedor||'—')}</td><td>${fmt(d.data_documento)}</td><td>${esc(d.categoria||'—')}</td><td>${esc(d.setor||'—')}</td><td>${money(d.valor)}</td><td>${statusBadge(d.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum documento cadastrado.')}`;$('#uploadDoc').onclick=docForm}
function docForm(){const x=modal('Enviar documento fiscal',`<form id="docForm"><div class="modal-body"><div class="field"><label>Arquivo</label><input name="file" type="file" accept="image/*,.pdf" required></div><div class="form-grid"><div class="field"><label>Fornecedor</label><input name="fornecedor"></div><div class="field"><label>Data</label><input name="data" type="date" value="${today()}"></div><div class="field"><label>Natureza</label><select name="categoria">${db.natures.map(n=>`<option>${esc(n.nome)}</option>`).join('')}</select></div><div class="field"><label>Setor</label><select name="setor">${db.sectors.map(s=>`<option>${esc(s.nome)}</option>`).join('')}</select></div><div class="field"><label>Valor</label><input name="valor" type="number" step="0.01" value="0"></div></div></div><div class="modal-foot"><button class="btn">Salvar documento</button></div></form>`);x.querySelector('#docForm').onsubmit=async e=>{e.preventDefault();const f=e.target,file=f.file.files[0],path=`${user.id}/financeiro-fiscal/${monthKey(f.data.value)}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;try{const up=await sb.storage.from('documentos').upload(path,file,{contentType:file.type||'application/octet-stream'});if(up.error)throw up.error;const row={nome:file.name,tipo:file.type,fornecedor:f.fornecedor.value||null,data_documento:f.data.value,categoria:f.categoria.value||null,setor:f.setor.value||null,valor:Number(f.valor.value||0),status:'Confirmado',storage_bucket:'documentos',storage_path:path,created_by:user.id};const r=await sb.from('financeiro_documentos').insert(row);if(r.error)throw r.error;if(row.valor>0){await sb.from('financeiro_fluxo').insert({data_movimento:row.data_documento,direcao:'Saída',descricao:`Documento fiscal • ${row.fornecedor||file.name}`,natureza:row.categoria,setor:row.setor,valor:row.valor,origem:'Documento fiscal',created_by:user.id})}x.remove();await load();documents();toast('Documento salvo.')}catch(err){toast(err.message,'error')}}}
function cashflow(){title('Fluxo de Caixa');const rows=[...db.cashflow.map(x=>({...x,_date:x.data_movimento,_desc:x.descricao,_dir:x.direcao,_nature:x.natureza,_value:Number(x.valor||0)})),...db.payments.filter(p=>p.status==='Pago').map(p=>({_date:(p.pago_em||p.vencimento).slice(0,10),_desc:accountName(p.conta_id),_dir:'Saída',_nature:db.accounts.find(a=>a.id===p.conta_id)?.categoria||'',_value:Number(p.valor||0),origem:'Contas'}))].sort((a,b)=>b._date.localeCompare(a._date));$('#content').innerHTML=`<div class="sheet-toolbar"><div class="notice">Visualização condensada em formato de planilha.</div><button class="btn" id="newMovement">+ Movimento</button></div>${rows.length?`<div class="table-wrap"><table class="table sheet-table"><thead><tr><th>Data</th><th>Descrição</th><th>Natureza</th><th>Tipo</th><th>Origem</th><th>Valor</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${fmt(r._date)}</td><td>${esc(r._desc)}</td><td>${esc(r._nature||'—')}</td><td>${statusBadge(r._dir)}</td><td>${esc(r.origem||'Manual')}</td><td class="${r._dir==='Entrada'?'kpi-positive':'kpi-negative'}"><b>${r._dir==='Entrada'?'+':'-'} ${money(r._value)}</b></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma movimentação financeira.')}`;$('#newMovement').onclick=movementForm}
function movementForm(){const x=modal('Nova movimentação',`<form id="moveForm"><div class="modal-body"><div class="form-grid"><div class="field"><label>Data</label><input name="data_movimento" type="date" value="${today()}" required></div><div class="field"><label>Tipo</label><select name="direcao"><option>Entrada</option><option>Saída</option></select></div><div class="field full"><label>Descrição</label><input name="descricao" required></div><div class="field"><label>Natureza</label><select name="natureza">${db.natures.map(n=>`<option>${esc(n.nome)}</option>`).join('')}</select></div><div class="field"><label>Setor</label><select name="setor">${db.sectors.map(s=>`<option>${esc(s.nome)}</option>`).join('')}</select></div><div class="field"><label>Valor</label><input name="valor" type="number" step="0.01" required></div></div></div><div class="modal-foot"><button class="btn">Salvar</button></div></form>`);x.querySelector('#moveForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.valor=Number(o.valor);o.origem='Manual';o.created_by=user.id;const {error}=await sb.from('financeiro_fluxo').insert(o);if(error)return toast(error.message,'error');x.remove();await load();cashflow();toast('Movimentação registrada.')}}
const BT=window.MCLBudgetTools;
let budgetSearch='',budgetFilter='';
const budgetViewModes=new Map();
const budgetData=b=>BT.detail(b),budgetTotals=d=>BT.totals({...d,etapas:d.etapas.map(s=>({...s,itens:s.itens.filter(i=>i.status!=='Cancelado')}))});
function budgetError(err){toast(err.message||'Não foi possível salvar o orçamento.','error')}
async function saveBudget(b,d,action,extra={}){
 if(!admin())throw new Error('Somente administradores podem alterar orçamentos.');
 const t=budgetTotals(d);d.historico=[...(d.historico||[]),{data:new Date().toISOString(),autor:profile.nome,acao:action}];
 let query=sb.from('financeiro_orcamentos').update({...extra,realizado:t.realizado,dados:{...(b.dados||{}),mcl_orcamento:d},updated_at:new Date().toISOString()}).eq('id',b.id);
 if(b.updated_at)query=query.eq('updated_at',b.updated_at);
 const r=await query.select('id').single();if(r.error)throw new Error(r.error.code==='PGRST116'?'Este orçamento foi alterado por outra pessoa. Reabra-o antes de salvar.':r.error.message);
 await load();return db.budgets.find(x=>x.id===b.id);
}
function budgetBind(root,selector,fn){$$(selector,root).forEach(el=>el.onclick=()=>Promise.resolve(fn(el)).catch(budgetError))}
function budgets(){
 title(admin()?'Orçamentos':'Meu Orçamento');
 const rows=(admin()?db.budgets:db.budgets.filter(b=>b.setor===profile.setor)).filter(b=>{const d=budgetData(b);return (!budgetFilter||d.status===budgetFilter)&&`${b.setor} ${d.titulo} ${d.responsavel}`.toLocaleLowerCase('pt-BR').includes(budgetSearch.toLocaleLowerCase('pt-BR'))});
 $('#content').innerHTML=`<div class="toolbar"><div class="left"><input id="budgetSearch" aria-label="Buscar orçamentos" placeholder="Buscar por nome, setor ou responsável" value="${esc(budgetSearch)}"><select id="budgetFilter" aria-label="Filtrar por status"><option value="">Todos os status</option>${['Em elaboração','Aprovado','Em execução','Concluído','Cancelado'].map(s=>`<option ${s===budgetFilter?'selected':''}>${s}</option>`).join('')}</select></div>${admin()?'<button class="btn" id="newBudget">+ Orçamento</button>':''}</div>${rows.length?`<div class="grid cols-3">${rows.map(b=>{const d=budgetData(b),t=budgetTotals(d),pct=b.limite?Math.round(t.realizado/Number(b.limite)*100):0;return `<article class="card budget-card"><h3>${esc(d.titulo||b.setor)}</h3><p class="muted">${esc(b.setor)} • ${esc(d.responsavel||'Sem responsável')}</p>${statusBadge(d.status)}<div class="budget-line"><span>Limite</span><strong>${money(b.limite)}</strong></div><div class="budget-line"><span>Previsto nos itens</span><strong>${money(t.previsto)}</strong></div><div class="budget-line"><span>Realizado</span><strong>${money(t.realizado)}</strong></div><div class="budget-line"><span>Saldo disponível</span><strong class="${b.limite-t.realizado<0?'kpi-negative':''}">${money(b.limite-t.realizado)}</strong></div><div class="progress"><i style="width:${Math.max(0,Math.min(100,pct))}%"></i></div><p class="muted">${pct}% utilizado • ${d.etapas.length} etapas • ${t.itens} itens</p><button class="btn small" data-budget-open="${b.id}">Abrir orçamento</button></article>`}).join('')}</div>`:empty('Nenhum orçamento encontrado.')}`;
 $('#budgetSearch').onchange=e=>{budgetSearch=e.target.value;budgets()};$('#budgetFilter').onchange=e=>{budgetFilter=e.target.value;budgets()};if(admin())$('#newBudget').onclick=()=>budgetForm();budgetBind(document,'[data-budget-open]',el=>budgetDetail(el.dataset.budgetOpen));
}
function budgetForm(b=null){
 const d=b?budgetData(b):{titulo:'',status:'Em elaboração',inicio:'',fim:'',responsavel:'',observacoes:'',base:0,etapas:[],documentos:[],historico:[]},names=[...new Set([...db.sectors.map(s=>s.nome),...(b?[b.setor]:[])])];
 const x=modal(b?'Editar orçamento':'Novo orçamento',`<form id="budgetForm"><div class="modal-body"><div class="form-grid"><div class="field full"><label>Nome do orçamento</label><input name="titulo" value="${esc(d.titulo)}" required maxlength="200"></div><div class="field"><label>Setor</label><select name="setor" required ${b?'disabled':''}>${names.map(s=>`<option ${s===b?.setor?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Em elaboração','Aprovado','Em execução','Concluído','Cancelado'].map(s=>`<option ${s===d.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Limite total (R$)</label><input name="limite" type="number" min="0" step="0.01" value="${b?.limite||0}" required></div><div class="field"><label>Realizado anterior aos itens (R$)</label><input name="base" type="number" min="0" step="0.01" value="${d.base||0}" required><small>Valor já registrado antes do detalhamento. Não repita nos novos itens.</small></div><div class="field"><label>Início</label><input name="inicio" type="date" value="${esc(d.inicio)}"></div><div class="field"><label>Fim</label><input name="fim" type="date" value="${esc(d.fim)}"></div><div class="field full"><label>Responsável</label><input name="responsavel" value="${esc(d.responsavel)}" maxlength="200"></div><div class="field full"><label>Observações</label><textarea name="observacoes" maxlength="10000">${esc(d.observacoes)}</textarea></div></div></div><div class="modal-foot"><button class="btn">Salvar orçamento</button></div></form>`);
 const f=$('#budgetForm',x);f.onsubmit=async e=>{e.preventDefault();const button=$('button[type="submit"],.modal-foot button',f);button.disabled=true;try{const o=Object.fromEntries(new FormData(f));if(o.fim&&o.inicio&&o.fim<o.inicio)throw new Error('O fim deve ser posterior ao início.');const nd={...d,...o,base:BT.amount(o.base)},limite=BT.amount(o.limite);delete nd.limite;delete nd.setor;
 if(b)await saveBudget(b,nd,'Editou os dados gerais do orçamento',{limite});else{nd.historico=[{data:new Date().toISOString(),autor:profile.nome,acao:'Criou o orçamento'}];if(db.budgets.some(z=>z.setor===o.setor))throw new Error('Este setor já possui orçamento. Abra o orçamento existente para editar ou adicionar etapas.');const r=await sb.from('financeiro_orcamentos').insert({setor:o.setor,limite,realizado:nd.base,dados:{mcl_orcamento:nd}}).select('id').single();if(r.error)throw r.error;await load()}
 x.remove();budgets();toast('Orçamento salvo.');}catch(err){budgetError(err)}finally{button.disabled=false}};
}
function budgetDetail(id){
 const b=db.budgets.find(o=>String(o.id)===String(id));if(!b)return;const d=budgetData(b),t=budgetTotals(d),x=modal(d.titulo||b.setor,`<div class="modal-body budget-detail"><div class="budget-view-switch" role="group" aria-label="Visualização do orçamento"><span>Visualização</span><div><button type="button" class="btn small" data-budget-mode="full" aria-pressed="true">Versão completa</button><button type="button" class="btn small ghost" data-budget-mode="reduced" aria-pressed="false">Versão reduzida</button></div></div><p>${esc(b.setor)} • ${esc(d.responsavel||'Sem responsável')} • ${fmt(d.inicio)} a ${fmt(d.fim)}</p>${statusBadge(d.status)}<div class="grid cols-3"><div class="card"><small>Limite</small><h3>${money(b.limite)}</h3></div><div class="card"><small>Previsto nos itens</small><h3>${money(t.previsto)}</h3></div><div class="card"><small>Realizado / saldo</small><h3>${money(t.realizado)} / ${money(b.limite-t.realizado)}</h3></div></div>${t.previsto>b.limite||t.realizado>b.limite?'<p class="notice orange">O orçamento ultrapassou o limite. Revise os gastos ou ajuste o limite.</p>':''}${d.base?`<p class="muted">Realizado anterior aos itens: ${money(d.base)}</p>`:''}<div class="card-actions">${admin()?'<button class="btn" data-action="stage">+ Etapa de gastos</button><button class="btn ghost" data-action="edit">Editar orçamento</button><button class="btn danger" data-action="delete">Excluir orçamento</button>':''}<button class="btn ghost" data-action="csv">Exportar planilha</button><button class="btn ghost" data-action="pdf">Baixar PDF</button></div>${d.observacoes?`<p style="white-space:pre-wrap">${esc(d.observacoes)}</p>`:''}<h3>Etapas de gastos</h3>${d.etapas.map((s,n)=>{const st=BT.stageTotals(s);return `<section class="card budget-stage"><div class="section-head"><h3>${n+1}. ${esc(s.nome)}</h3><div class="budget-stage-summary"><span class="budget-reduced-only">Previsto: <b>${money(st.previsto)}</b></span>${statusBadge(s.status)}</div></div><p class="muted budget-full-only">${esc(s.responsavel||'Sem responsável')} • Prazo: ${fmt(s.prazo)}</p><p class="budget-full-only">Limite da etapa: <b>${money(s.limite)}</b> • Previsto: <b>${money(st.previsto)}</b> • Realizado: <b>${money(st.realizado)}</b> • Saldo: <b>${money(s.limite-st.realizado)}</b></p>${st.previsto>s.limite||st.realizado>s.limite?'<p class="notice orange">Esta etapa ultrapassou o limite.</p>':''}${s.observacoes?`<p class="budget-full-only" style="white-space:pre-wrap">${esc(s.observacoes)}</p>`:''}${admin()?`<div class="card-actions"><button class="btn small" data-stage-add="${esc(s.id)}">+ Gasto</button><button class="btn small ghost" data-stage-edit="${esc(s.id)}">Editar etapa</button><button class="btn small ghost budget-full-only" data-stage-copy="${esc(s.id)}">Duplicar</button><button class="btn small ghost budget-full-only" data-stage-up="${esc(s.id)}" ${n===0?'disabled':''}>↑ Mover acima</button><button class="btn small danger budget-full-only" data-stage-del="${esc(s.id)}">Excluir etapa</button></div>`:''}<div class="table-wrap"><table class="table"><thead><tr><th>Gasto</th><th class="budget-full-only">Fornecedor / categoria</th><th class="budget-full-only">Prazo</th><th class="budget-full-only">Quantidade</th><th class="budget-full-only">Unitário / desconto</th><th class="budget-item-planned">Previsto</th><th class="budget-full-only">Realizado</th><th class="budget-full-only">Status</th>${admin()?'<th class="budget-item-actions">Ações</th>':''}</tr></thead><tbody>${s.itens.map(i=>`<tr><td>${esc(i.descricao)}${i.observacoes?`<small class="muted budget-full-only">${esc(i.observacoes)}</small>`:''}${i.status==='Cancelado'?`<span class="budget-reduced-only">${statusBadge(i.status)}</span>`:''}</td><td class="budget-full-only">${esc(i.fornecedor||'—')}<br>${esc(i.categoria||'')}</td><td class="budget-full-only">${fmt(i.prazo)}</td><td class="budget-full-only">${esc(i.quantidade)}</td><td class="budget-full-only">${money(i.unitario)} / ${money(i.desconto)}</td><td class="budget-item-planned"><b>${money(BT.itemTotal(i))}</b></td><td class="budget-full-only">${money(i.realizado)}</td><td class="budget-full-only">${statusBadge(i.status)}</td>${admin()?`<td class="budget-item-actions"><button class="btn small ghost" data-item-edit="${esc(i.id)}" data-stage="${esc(s.id)}">Editar</button><button class="btn small danger" data-item-del="${esc(i.id)}" data-stage="${esc(s.id)}">Excluir</button></td>`:''}</tr>`).join('')||`<tr><td data-budget-empty colspan="${admin()?9:8}">Nenhum gasto nesta etapa.</td></tr>`}</tbody></table></div></section>`}).join('')||empty('Crie etapas para organizar os gastos do orçamento.')}<h3>Documentos e comprovantes</h3>${admin()?'<button class="btn" data-action="upload">Enviar documentos</button>':''}<p class="muted">PDF, JPG, PNG, DOCX e XLSX • até 20 MB por arquivo</p>${(d.documentos||[]).map(doc=>`<div class="mini-row"><span><b>${esc(doc.nome)}</b><small>${esc(doc.rotulo||'Documento')} • ${esc(d.etapas.find(s=>s.id===doc.etapa)?.nome||'Orçamento')} • ${esc(doc.autor||'')} • ${fmt(doc.data?.slice(0,10))}</small></span><div><button class="btn small ghost" data-doc-open="${esc(doc.id)}">Visualizar</button><button class="btn small ghost" data-doc-download="${esc(doc.id)}">Baixar</button>${admin()?`<button class="btn small danger" data-doc-del="${esc(doc.id)}">Excluir</button>`:''}</div></div>`).join('')||empty('Nenhum documento anexado.')}<details><summary>Histórico de alterações (${d.historico?.length||0})</summary>${[...(d.historico||[])].reverse().map(h=>`<p>${esc(new Date(h.data).toLocaleString('pt-BR'))} • ${esc(h.autor)} • ${esc(h.acao)}</p>`).join('')}</details></div>`,true);
 const applyMode=mode=>{
  const reduced=mode==='reduced';budgetViewModes.set(String(id),reduced?'reduced':'full');
  $('.budget-detail',x).classList.toggle('is-reduced',reduced);
  $('.modal',x).style.width=reduced?'min(760px,96vw)':'min(1000px,96vw)';
  $('.modal',x).style.maxWidth='100%';
  $$('[data-budget-empty]',x).forEach(cell=>cell.colSpan=reduced?(admin()?3:2):(admin()?9:8));
  $$('[data-budget-mode]',x).forEach(button=>{const selected=button.dataset.budgetMode===(reduced?'reduced':'full');button.setAttribute('aria-pressed',String(selected));button.classList.toggle('ghost',!selected)});
 };
 applyMode(budgetViewModes.get(String(id))||'full');
 budgetBind(x,'[data-budget-mode]',button=>applyMode(button.dataset.budgetMode));
 const refresh=()=>{x.remove();budgetDetail(id);budgets()};
 budgetBind(x,'[data-action]',el=>{const a=el.dataset.action;if(a==='edit'){x.remove();budgetForm(b)}if(a==='stage')budgetStageForm(b,null,refresh);if(a==='upload')budgetUpload(b,refresh);if(a==='delete')return budgetDelete(b,x);if(a==='csv'||a==='pdf')budgetExport(b,a)});
 budgetBind(x,'[data-stage-edit]',el=>budgetStageForm(b,el.dataset.stageEdit,refresh));budgetBind(x,'[data-stage-add]',el=>budgetItemForm(b,el.dataset.stageAdd,null,refresh));budgetBind(x,'[data-item-edit]',el=>budgetItemForm(b,el.dataset.stage,el.dataset.itemEdit,refresh));
 budgetBind(x,'[data-item-del]',async el=>{if(!confirm('Excluir este gasto e recalcular os totais?'))return;const nd=budgetData(b),s=nd.etapas.find(s=>s.id===el.dataset.stage);if(nd.documentos.some(z=>z.item===el.dataset.itemDel))throw new Error('Exclua primeiro os documentos vinculados a este gasto.');const i=s.itens.find(i=>i.id===el.dataset.itemDel);s.itens=s.itens.filter(i=>i.id!==el.dataset.itemDel);await saveBudget(b,nd,`Excluiu o gasto ${i.descricao}`);refresh()});
 budgetBind(x,'[data-stage-del]',async el=>{if(!confirm('Excluir esta etapa e todos os gastos dela? Os totais serão recalculados.'))return;const nd=budgetData(b);if(nd.documentos.some(z=>z.etapa===el.dataset.stageDel))throw new Error('Exclua primeiro os documentos vinculados a esta etapa.');const s=nd.etapas.find(s=>s.id===el.dataset.stageDel);nd.etapas=nd.etapas.filter(s=>s.id!==el.dataset.stageDel);await saveBudget(b,nd,`Excluiu a etapa ${s.nome}`);refresh()});
 budgetBind(x,'[data-stage-copy]',async el=>{const nd=budgetData(b),s=structuredClone(nd.etapas.find(s=>s.id===el.dataset.stageCopy));s.id=uid();s.nome+=' (cópia)';s.status='Pendente';s.itens=s.itens.map(i=>({...i,id:uid(),realizado:0,status:'Previsto'}));nd.etapas.push(s);await saveBudget(b,nd,`Duplicou a etapa ${s.nome}`);refresh()});
 budgetBind(x,'[data-stage-up]',async el=>{const nd=budgetData(b),n=nd.etapas.findIndex(s=>s.id===el.dataset.stageUp);if(n<1)return;[nd.etapas[n-1],nd.etapas[n]]=[nd.etapas[n],nd.etapas[n-1]];await saveBudget(b,nd,'Reordenou as etapas');refresh()});
 for(const mode of ['open','download'])budgetBind(x,`[data-doc-${mode}]`,async el=>{const doc=d.documentos.find(z=>z.id===el.dataset[mode==='open'?'docOpen':'docDownload']);if(mode==='download'){const r=await sb.storage.from('documentos').download(doc.path);if(r.error)throw r.error;budgetDownload(r.data,doc.nome)}else{const w=window.open('about:blank','_blank');try{const r=await sb.storage.from('documentos').createSignedUrl(doc.path,120);if(r.error)throw r.error;if(w){w.opener=null;w.location=r.data.signedUrl}else toast('Permita a abertura de novas abas para visualizar o documento.','error')}catch(err){w?.close();throw err}}});
 budgetBind(x,'[data-doc-del]',async el=>{if(!confirm('Excluir este documento do orçamento?'))return;const nd=budgetData(b),doc=nd.documentos.find(z=>z.id===el.dataset.docDel);nd.documentos=nd.documentos.filter(z=>z.id!==doc.id);await saveBudget(b,nd,`Removeu o documento ${doc.nome}`);const r=await sb.storage.from('documentos').remove([doc.path]);refresh();if(r.error)toast('Vínculo removido; falha ao excluir o arquivo armazenado.','error')});
}
async function budgetDelete(b,x){if(!admin())throw new Error('Acesso negado.');if(budgetData(b).documentos.length)throw new Error('Exclua os documentos anexados antes de excluir o orçamento.');if(!confirm(`Excluir o orçamento ${budgetData(b).titulo} e todas as etapas e gastos?`))return;let q=sb.from('financeiro_orcamentos').delete().eq('id',b.id);if(b.updated_at)q=q.eq('updated_at',b.updated_at);const r=await q.select('id').single();if(r.error)throw new Error(r.error.code==='PGRST116'?'Orçamento alterado por outra pessoa. Reabra antes de excluir.':r.error.message);x.remove();await load();budgets();toast('Orçamento excluído.')}
function budgetStageForm(b,id,refresh){const d=budgetData(b),s=d.etapas.find(s=>s.id===id)||{id:uid(),nome:'',status:'Pendente',responsavel:'',prazo:'',limite:0,observacoes:'',itens:[]},x=modal(id?'Editar etapa':'Nova etapa',`<form><div class="modal-body"><div class="form-grid">${[['nome','Nome da etapa','text',s.nome],['responsavel','Responsável','text',s.responsavel],['prazo','Prazo','date',s.prazo],['limite','Limite da etapa (R$)','number',s.limite]].map(([n,l,t,v])=>`<div class="field"><label>${l}</label><input name="${n}" type="${t}" value="${esc(v)}" ${n==='nome'?'required maxlength="200"':''} ${t==='number'?'min="0" step="0.01" required':''}></div>`).join('')}<div class="field"><label>Status</label><select name="status">${['Pendente','Em andamento','Concluída','Cancelada'].map(v=>`<option ${v===s.status?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Observações</label><textarea name="observacoes">${esc(s.observacoes)}</textarea></div></div></div><div class="modal-foot"><button class="btn">Salvar etapa</button></div></form>`);$('form',x).onsubmit=async e=>{e.preventDefault();const btn=$('.modal-foot button',x);btn.disabled=true;try{const o=Object.fromEntries(new FormData(e.target)),ns={...s,...o,limite:BT.amount(o.limite)};if(id)d.etapas=d.etapas.map(z=>z.id===id?ns:z);else d.etapas.push(ns);await saveBudget(b,d,`${id?'Editou':'Criou'} a etapa ${ns.nome}`);x.remove();refresh()}catch(err){budgetError(err)}finally{btn.disabled=false}}}
function budgetItemForm(b,stageId,id,refresh){const d=budgetData(b),s=d.etapas.find(z=>z.id===stageId),i=s.itens.find(z=>z.id===id)||{id:uid(),descricao:'',quantidade:1,unitario:0,desconto:0,realizado:0,status:'Previsto',fornecedor:'',categoria:'',prazo:'',observacoes:''},x=modal(id?'Editar gasto':'Novo gasto',`<form><div class="modal-body"><div class="form-grid">${[['descricao','Descrição','text'],['fornecedor','Fornecedor','text'],['categoria','Categoria / natureza','text'],['prazo','Vencimento / prazo','date'],['quantidade','Quantidade','number'],['unitario','Valor unitário (R$)','number'],['desconto','Desconto total (R$)','number'],['realizado','Realizado (R$)','number']].map(([n,l,t])=>`<div class="field"><label>${l}</label><input name="${n}" type="${t}" value="${esc(i[n])}" ${n==='descricao'?'required maxlength="500"':''} ${t==='number'?`step="0.01" min="${n==='quantidade'?'0.01':'0'}" required`:''}></div>`).join('')}<div class="field"><label>Status</label><select name="status">${['Previsto','Comprometido','Parcialmente pago','Pago','Cancelado'].map(v=>`<option ${v===i.status?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Observações</label><textarea name="observacoes">${esc(i.observacoes)}</textarea></div></div><p class="notice" id="budgetCalc"></p><p class="muted">O realizado compõe este orçamento. Registre o pagamento no Fluxo de Caixa para movimentar o caixa.</p></div><div class="modal-foot"><button class="btn">Salvar gasto</button></div></form>`),f=$('form',x);const calc=()=>{try{$('#budgetCalc',x).textContent=`Total previsto: ${money(BT.itemTotal(Object.fromEntries(new FormData(f))))}`}catch(err){$('#budgetCalc',x).textContent=err.message}};f.oninput=calc;calc();f.onsubmit=async e=>{e.preventDefault();const btn=$('.modal-foot button',x);btn.disabled=true;try{const o=Object.fromEntries(new FormData(f));BT.itemTotal(o);const ni={...i,...o,quantidade:Number(o.quantidade),unitario:BT.amount(o.unitario),desconto:BT.amount(o.desconto),realizado:BT.amount(o.realizado)};if(ni.status==='Cancelado'&&ni.realizado>0)throw new Error('Um gasto com valor realizado não pode ser cancelado. Zere ou corrija o realizado primeiro.');if(ni.status==='Pago'&&ni.realizado===0)throw new Error('Informe o valor realizado do gasto pago.');if(id)s.itens=s.itens.map(z=>z.id===id?ni:z);else s.itens.push(ni);await saveBudget(b,d,`${id?'Editou':'Criou'} o gasto ${ni.descricao}`);x.remove();refresh()}catch(err){budgetError(err)}finally{btn.disabled=false}}}
function budgetUpload(b,refresh){const d=budgetData(b),x=modal('Enviar documentos ao orçamento',`<form><div class="modal-body"><div class="field"><label>Arquivos</label><input name="files" type="file" multiple required accept=".pdf,.jpg,.jpeg,.png,.docx,.xlsx"><small>Até 20 MB por arquivo.</small></div><div class="field"><label>Tipo / descrição</label><input name="rotulo" placeholder="Cotação, contrato, nota fiscal, comprovante…" maxlength="200"></div><div class="field"><label>Vincular à etapa</label><select name="etapa"><option value="">Orçamento geral</option>${d.etapas.map(s=>`<option value="${esc(s.id)}">${esc(s.nome)}</option>`).join('')}</select></div><div class="field"><label>Vincular ao gasto</label><select name="item"><option value="">Sem gasto específico</option></select></div><p class="notice">Anexar um documento não altera os valores do orçamento.</p><p role="status" id="budgetUploadStatus"></p></div><div class="modal-foot"><button class="btn">Enviar documentos</button></div></form>`),f=$('form',x);f.elements.etapa.onchange=()=>{const s=d.etapas.find(s=>s.id===f.elements.etapa.value);f.elements.item.innerHTML='<option value="">Sem gasto específico</option>'+(s?.itens||[]).map(i=>`<option value="${esc(i.id)}">${esc(i.descricao)}</option>`).join('')};let sending=false;x.querySelector('[data-close]').onclick=()=>{if(!sending)x.remove()};f.onsubmit=async e=>{e.preventDefault();if(sending)return;sending=true;const btn=$('.modal-foot button',x);btn.disabled=true;const uploaded=[];let saved=false;try{const files=[...f.elements.files.files];if(files.length>20)throw new Error('Envie até 20 arquivos por vez.');for(const file of files){if(file.size>20*1024*1024||file.size===0||! /\.(pdf|jpe?g|png|docx|xlsx)$/i.test(file.name))throw new Error(`Arquivo inválido ou maior que 20 MB: ${file.name}`)}for(const [n,file] of files.entries()){$('#budgetUploadStatus',x).textContent=`Enviando ${n+1} de ${files.length}…`;const path=`${user.id}/orcamentos/${b.id}/${uid()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`,r=await sb.storage.from('documentos').upload(path,file,{upsert:false,contentType:file.type||'application/octet-stream'});if(r.error)throw r.error;uploaded.push(path);d.documentos.push({id:uid(),nome:file.name,path,tipo:file.type,tamanho:file.size,rotulo:f.elements.rotulo.value,etapa:f.elements.etapa.value,item:f.elements.item.value,autor:profile.nome,data:new Date().toISOString()})}await saveBudget(b,d,`Anexou ${files.length} documento(s)`);saved=true;x.remove();refresh();toast('Documentos enviados.')}catch(err){if(!saved&&uploaded.length){const cleanup=await sb.storage.from('documentos').remove(uploaded);if(cleanup.error)console.warn('Falha na limpeza de uploads',cleanup.error.message)}budgetError(err)}finally{sending=false;btn.disabled=false}}}
function budgetDownload(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function budgetExport(b,kind){const d=budgetData(b),t=budgetTotals(d),rows=d.etapas.flatMap(s=>s.itens.map(i=>[s.nome,i.descricao,i.fornecedor||'',i.categoria||'',i.prazo||'',i.quantidade,i.unitario,i.desconto,BT.itemTotal(i),i.realizado,i.status]));if(kind==='csv'){const cell=v=>`"${String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')}"`;const lines=[['Orçamento',d.titulo,'Setor',b.setor],['Limite',b.limite,'Previsto',t.previsto,'Realizado',t.realizado,'Saldo',b.limite-t.realizado],['Realizado anterior aos itens',d.base],['Etapa','Descrição','Fornecedor','Categoria','Prazo','Quantidade','Unitário','Desconto','Previsto','Realizado','Status'],...rows];budgetDownload(new Blob(['\uFEFF'+lines.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'orcamento-mcl.csv');return}if(!window.jspdf)throw new Error('Não foi possível carregar a exportação PDF.');const pdf=new window.jspdf.jsPDF({orientation:'landscape'});pdf.setFontSize(16);pdf.text('Minha Casa Legal — Orçamento',14,16);pdf.setFontSize(10);pdf.text(pdf.splitTextToSize(`${d.titulo} | ${b.setor} | ${d.status}`,265),14,25);pdf.text(`Limite: ${money(b.limite)} | Previsto: ${money(t.previsto)} | Realizado: ${money(t.realizado)} | Saldo: ${money(b.limite-t.realizado)}`,14,40);pdf.text(`Realizado anterior aos itens: ${money(d.base)}`,14,47);pdf.autoTable({startY:53,head:[['Etapa','Gasto','Fornecedor','Categoria','Prazo','Qtd.','Unitário','Desconto','Previsto','Realizado','Status']],body:rows.map(r=>r.map((v,n)=>[6,7,8,9].includes(n)?money(v):v)),styles:{fontSize:8},margin:{left:14,right:14}});pdf.save('orcamento-mcl.pdf')}
function trips(){title('Viagens');const rows=admin()?db.trips:db.trips.filter(t=>t.created_by===user.id);$('#content').innerHTML=`<div class="toolbar"><div class="left"><div class="notice">Despesas e comprovações de viagens.</div></div><div class="right"><button class="btn" id="newTrip">+ Nova viagem</button></div></div>${rows.length?`<div class="grid cols-3">${rows.map(t=>`<article class="card trip-card"><div style="display:flex;justify-content:space-between;gap:8px"><h3>${esc(t.cidade)}</h3>${statusBadge(t.status)}</div><div class="muted">${fmt(t.data_inicio)} ${t.data_fim?`a ${fmt(t.data_fim)}`:''}</div><div class="trip-meta"><span><small>Colaborador</small><b>${esc(t.colaborador||'—')}</b></span><span><small>Setor</small><b>${esc(t.setor||'—')}</b></span><span><small>Declarado</small><b>${money(t.valor_declarado)}</b></span><span><small>Comprovado</small><b>${money(t.valor_comprovado)}</b></span></div>${admin()||t.created_by===user.id?`<div class="card-actions"><button class="btn small ghost" data-trip-edit="${t.id}">Editar</button>${admin()?`<button class="btn small danger" data-trip-del="${t.id}">Excluir</button>`:''}</div>`:''}</article>`).join('')}</div>`:empty('Nenhuma viagem cadastrada.')}`;$('#newTrip').onclick=()=>tripForm();$$('[data-trip-edit]').forEach(b=>b.onclick=()=>tripForm(db.trips.find(t=>String(t.id)===b.dataset.tripEdit)));$$('[data-trip-del]').forEach(b=>b.onclick=async()=>{const t=db.trips.find(x=>String(x.id)===b.dataset.tripDel);if(!t||!confirm(`Excluir a viagem para ${t.cidade}?`))return;const {error}=await sb.from('financeiro_viagens').delete().eq('id',t.id);if(error)return toast(error.message,'error');await load();trips()})}
function tripForm(t=null){const sectorNames=[...new Set([...db.sectors.map(s=>s.nome),...(t?.setor?[t.setor]:[])])];const x=modal(t?'Editar viagem':'Nova viagem',`<form id="tripForm"><div class="modal-body"><div class="form-grid"><div class="field"><label>Cidade</label><input name="cidade" value="${esc(t?.cidade||'')}" required></div><div class="field"><label>Projeto</label><input name="projeto" value="${esc(t?.projeto||'')}"></div><div class="field"><label>Início</label><input name="data_inicio" type="date" value="${esc(t?.data_inicio||today())}"></div><div class="field"><label>Fim</label><input name="data_fim" type="date" value="${esc(t?.data_fim||'')}"></div><div class="field"><label>Colaborador</label><input name="colaborador" value="${esc(t?t.colaborador||'':profile.nome)}"></div><div class="field"><label>Setor</label><select name="setor">${sectorNames.map(s=>`<option ${t&&s===t.setor?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Valor declarado</label><input name="valor_declarado" type="number" step="0.01" value="${Number(t?.valor_declarado||0)}"></div><div class="field"><label>Valor comprovado</label><input name="valor_comprovado" type="number" step="0.01" value="${Number(t?.valor_comprovado||0)}"></div></div></div><div class="modal-foot"><button class="btn">Salvar</button></div></form>`);x.querySelector('#tripForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.valor_declarado=Number(o.valor_declarado);o.valor_comprovado=Number(o.valor_comprovado);o.status=Math.abs(o.valor_declarado-o.valor_comprovado)<.01?'Aprovada':'Pendente';if(!o.data_fim)o.data_fim=null;let error;if(t){({error}=await sb.from('financeiro_viagens').update(o).eq('id',t.id))}else{o.created_by=user.id;({error}=await sb.from('financeiro_viagens').insert(o))}if(error)return toast(error.message,'error');x.remove();await load();trips()}}
function planning(){title('Planejamento');$('#content').innerHTML=`<div class="toolbar"><div class="left"><div class="notice">Entradas e saídas previstas por mês.</div></div><div class="right"><button class="btn" id="newPlan">+ Mês</button></div></div>${db.planning.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Mês</th><th>Entradas previstas</th><th>Saídas previstas</th><th>Saldo projetado</th></tr></thead><tbody>${db.planning.sort((a,b)=>a.mes.localeCompare(b.mes)).map(p=>`<tr><td><b>${fmt(p.mes)}</b></td><td>${money(p.entradas_previstas)}</td><td>${money(p.saidas_previstas)}</td><td class="${Number(p.entradas_previstas)>=Number(p.saidas_previstas)?'kpi-positive':'kpi-negative'}"><b>${money(Number(p.entradas_previstas)-Number(p.saidas_previstas))}</b></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum mês planejado.')}`;$('#newPlan').onclick=planForm}
function planForm(){const x=modal('Planejamento mensal',`<form id="planForm"><div class="modal-body"><div class="field"><label>Mês</label><input name="mesx" type="month" value="${monthKey()}" required></div><div class="field"><label>Entradas previstas</label><input name="entradas_previstas" type="number" step="0.01" value="0"></div><div class="field"><label>Saídas previstas</label><input name="saidas_previstas" type="number" step="0.01" value="0"></div></div><div class="modal-foot"><button class="btn">Salvar</button></div></form>`);x.querySelector('#planForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),o={mes:`${f.get('mesx')}-01`,entradas_previstas:Number(f.get('entradas_previstas')),saidas_previstas:Number(f.get('saidas_previstas'))};const {error}=await sb.from('financeiro_planejamento').upsert(o,{onConflict:'mes'});if(error)return toast(error.message,'error');x.remove();await load();planning()}}
function reports(){title('Relatórios');const inc=incomeValue(),out=paidValue(),open=db.payments.filter(p=>p.status!=='Pago').reduce((s,p)=>s+Number(p.valor||0),0);$('#content').innerHTML=`<div class="grid cols-3"><div class="card metric"><h3>Entradas acumuladas</h3><b>${money(inc)}</b></div><div class="card metric"><h3>Saídas acumuladas</h3><b>${money(out)}</b></div><div class="card metric"><h3>Obrigações em aberto</h3><b>${money(open)}</b></div></div><h3 class="section-title">Resumo executivo</h3><div class="report-text">O Financeiro MCL possui <b>${db.accounts.length}</b> contas cadastradas, <b>${db.payments.length}</b> pagamentos, <b>${db.documents.length}</b> documentos fiscais e <b>${db.trips.length}</b> viagens. O resultado financeiro acumulado registrado é de <b>${money(inc-out)}</b>.</div>`}
/* Cadastros: naturezas e setores com editar, ativar/inativar e excluir (excluir e renomear só quando o item não está em uso). */
function registerUses(kind,name){const n=String(name||'').trim().toLowerCase();if(!n)return 0;const eq=v=>String(v||'').trim().toLowerCase()===n;let c=0;if(kind==='natureza'){c+=db.cashflow.filter(r=>eq(r.natureza)||eq(r.categoria)).length;c+=db.accounts.filter(r=>eq(r.categoria)).length;c+=db.documents.filter(r=>eq(r.categoria)).length}else{c+=db.cashflow.filter(r=>eq(r.setor)).length;c+=db.accounts.filter(r=>eq(r.setor)).length;c+=db.documents.filter(r=>eq(r.setor)).length;c+=db.budgets.filter(r=>eq(r.setor)).length;c+=db.trips.filter(r=>eq(r.setor)).length;c+=db.profiles.filter(r=>eq(r.setor)).length}return c}
function registerRow(kind,item){const off=item.ativo===false;return `<div class="register-row" style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:9px 0;border-bottom:1px solid var(--line)"><span>${esc(item.nome)}${off?' <span class="badge">Inativo</span>':''}</span><span style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;justify-content:flex-end">${kind==='natureza'?`<span class="badge">${esc(item.tipo||'')}</span>`:''}<button class="btn small ghost" data-reg-edit="${kind}:${item.id}">Editar</button><button class="btn small ghost" data-reg-toggle="${kind}:${item.id}">${off?'Ativar':'Inativar'}</button><button class="btn small danger" data-reg-del="${kind}:${item.id}">Excluir</button></span></div>`}
function registers(){title('Cadastros');$('#content').innerHTML=`<div class="grid cols-2"><section class="card"><div class="toolbar"><h3 style="margin:0;color:var(--primary)">Naturezas</h3><button class="btn small" id="addNature">+ Adicionar</button></div>${db.natures.length?db.natures.map(n=>registerRow('natureza',n)).join(''):empty()}</section><section class="card"><div class="toolbar"><h3 style="margin:0;color:var(--primary)">Setores</h3><button class="btn small" id="addSector">+ Adicionar</button></div>${db.sectors.length?db.sectors.map(s=>registerRow('setor',s)).join(''):empty()}</section></div>`;$('#addNature').onclick=()=>simpleRegister('financeiro_naturezas','Nova natureza',['nome','tipo']);$('#addSector').onclick=()=>simpleRegister('financeiro_setores','Novo setor',['nome']);
const find=v=>{const [kind,id]=String(v).split(':');const list=kind==='natureza'?db.natures:db.sectors;return {kind,item:list.find(x=>String(x.id)===id),table:kind==='natureza'?'financeiro_naturezas':'financeiro_setores'}};
$$('[data-reg-edit]').forEach(b=>b.onclick=()=>{const {kind,item,table}=find(b.dataset.regEdit);if(item)simpleRegister(table,kind==='natureza'?'Editar natureza':'Editar setor',kind==='natureza'?['nome','tipo']:['nome'],item,kind)});
$$('[data-reg-toggle]').forEach(b=>b.onclick=async()=>{const {item,table}=find(b.dataset.regToggle);if(!item)return;const {error}=await sb.from(table).update({ativo:item.ativo===false}).eq('id',item.id);if(error)return toast(error.message,'error');await load();registers()});
$$('[data-reg-del]').forEach(b=>b.onclick=async()=>{const {kind,item,table}=find(b.dataset.regDel);if(!item)return;const uses=registerUses(kind,item.nome);if(uses)return toast(`"${item.nome}" está em uso em ${uses} registro(s). Use "Inativar" para não alterar esses lançamentos.`,'error');if(!confirm(`Excluir "${item.nome}"?`))return;const {error}=await sb.from(table).delete().eq('id',item.id);if(error)return toast(error.message,'error');await load();registers()})}
function simpleRegister(table,t,fields,item=null,kind=''){const uses=item?registerUses(kind,item.nome):0;const x=modal(t,`<form id="reg"><div class="modal-body">${fields.map(f=>`<div class="field"><label>${f==='nome'?'Nome':'Tipo'}</label>${f==='tipo'?`<select name="tipo"><option ${item?.tipo==='Despesa'?'selected':''}>Despesa</option><option ${item?.tipo==='Receita'?'selected':''}>Receita</option></select>`:`<input name="${f}" value="${esc(item?.[f]||'')}" ${uses?'readonly':''} required>`}</div>`).join('')}${uses?`<div class="notice orange">Este item está em uso em ${uses} registro(s); o nome não pode ser alterado para não desvincular esses lançamentos.</div>`:''}</div><div class="modal-foot"><button class="btn">Salvar</button></div></form>`);x.querySelector('#reg').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(uses)delete o.nome;const {error}=item?await sb.from(table).update(o).eq('id',item.id):await sb.from(table).insert({...o,ativo:true});if(error)return toast(error.message,'error');x.remove();await load();registers()}}
function users(){title('Usuários');$('#content').innerHTML=`<div class="toolbar"><div class="left"><div class="notice">Cada usuário mantém o mesmo ID ao editar e-mail, setor, função ou senha.</div></div><div class="right"><button class="btn" id="newUser">+ Usuário</button></div></div><div class="user-grid">${db.profiles.length?db.profiles.map(u=>`<article class="user-card"><div class="user-card-head"><div><h3>${esc(u.nome)}</h3><div class="muted">${esc(u.email||'')}</div></div>${statusBadge(u.ativo===false?'Inativo':'Ativo')}</div><div class="user-meta"><span class="badge">${esc(u.tipo||'Funcionário')}</span><span class="badge orange">${esc(u.setor||'—')}</span></div><button class="btn ghost small" data-user="${u.id}">Editar usuário</button></article>`).join(''):empty('Nenhum usuário cadastrado.')}</div>`;$('#newUser').onclick=()=>userForm();$$('[data-user]').forEach(b=>b.onclick=()=>userForm(b.dataset.user))}
function userForm(id=''){const u=db.profiles.find(x=>x.id===id),sectors=[...new Set([...db.sectors.map(s=>s.nome),...(u?.setor?[u.setor]:[])])],roles=[...new Set(['Funcionário','Administrador','Financeiro','Comercial','Projetos','Topografia','Marketing','Pós-protocolo','Atendimentos',...(u?.tipo?[u.tipo]:[])])];const x=modal(u?'Editar usuário':'Novo usuário',`<form id="userForm"><div class="modal-body"><div class="form-grid"><div class="field"><label>Nome</label><input name="nome" value="${esc(u?.nome||'')}" required></div><div class="field"><label>E-mail</label><input name="email" type="email" value="${esc(u?.email||'')}" required></div><div class="field"><label>Setor</label><select name="setor">${sectors.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Função</label><select name="tipo">${roles.map(r=>`<option>${esc(r)}</option>`).join('')}</select></div><div class="field full"><label>${u?'Nova senha (deixe vazio para manter)':'Senha'}</label><input name="password" type="password" minlength="8" ${u?'':'required'}></div>${u?'<label class="check full"><input name="ativo" type="checkbox"> Usuário ativo</label>':''}</div></div><div class="modal-foot"><button class="btn">Salvar usuário</button></div></form>`);const f=x.querySelector('#userForm');if(u){f.setor.value=u.setor||sectors[0]||'';f.tipo.value=u.tipo||'Funcionário';f.ativo.checked=u.ativo!==false}f.onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(u){o.action='update';o.userId=u.id;o.ativo=f.ativo.checked;if(!o.password)delete o.password}else o.action='create';try{await invoke('admin-users',o);x.remove();await load();users();toast('Usuário salvo.')}catch(err){toast(err.message,'error')}}}
sb.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT')login()});bootstrap();
})();